INSERT INTO public.recognition_categories (tier_id, slug, name, tagline, sort_order)
SELECT t.id, i.slug, i.name, i.tagline, i.sort_order
FROM input i JOIN public.recognition_tiers t ON t.slug = i.tier_slug
JOIN cyc ON t.cycle_id = cyc.id
ON CONFLICT (tier_id, slug) DO UPDATE SET name=EXCLUDED.name, tagline=EXCLUDED.tagline, sort_order=EXCLUDED.sort_order;

-- Ensure derived registry parent slugs exist under Gold-Blue Garnet
WITH cyc AS (SELECT id FROM public.recognition_cycles WHERE slug='nesa-africa-2026'),
tier AS (SELECT t.id FROM public.recognition_tiers t JOIN cyc ON t.cycle_id=cyc.id WHERE t.slug='gold-blue-garnet'),
extras(slug, name, tagline) AS (VALUES
  ('edutech-innovation', 'EduTech Innovation', 'EdTech startups and initiatives scaling African learning.'),
  ('media-advocacy', 'Media for Education Advocacy', 'Print, radio, television and digital media championing education.'),
  ('ngo-advancement', 'NGOs Advancing Education (Registry)', 'Registry-derived NGO subcategories for Nigeria and Africa.'),
  ('stem-programme', 'STEM Education Programmes', 'Programme-level STEM excellence, inclusion and outreach.'),
  ('creative-arts', 'Creative Arts for Education', 'Film, music, literature and performing arts advancing learning.'),
  ('education-friendly-state', 'Education-Friendly States', 'State-level policy and implementation excellence.'),
  ('tertiary-library', 'Tertiary Institution Libraries', 'University, polytechnic, college of education and nursing libraries.'),
  ('research-excellence', 'Research Excellence', 'Agricultural, pharmaceutical and environmental research institutes.'),
  ('christian-education-impact', 'Christian Education Impact', 'Christian-led education infrastructure, scholarships and advocacy.'),
  ('islamic-education-impact', 'Islamic Education Impact', 'Islamic-led education infrastructure, scholarships and advocacy.'),
  ('political-leadership', 'Political Leadership for Education', 'Political leaders driving scholarships, infrastructure and advocacy.'),
