)
INSERT INTO public.recognition_categories (tier_id, slug, name, tagline, sort_order)
SELECT (SELECT id FROM tier), e.slug, e.name, e.tagline, 100
FROM extras e
ON CONFLICT (tier_id, slug) DO NOTHING;

