INSERT INTO public.recognition_subcategories (category_id, slug, name, description, sort_order)
SELECT c.id, i.slug, i.name, i.description, i.sort_order
FROM input i JOIN public.recognition_categories c ON c.slug = i.cat_slug
ON CONFLICT (category_id, slug) DO UPDATE SET name=EXCLUDED.name, description=EXCLUDED.description, sort_order=EXCLUDED.sort_order;
